import sys, json
lines = sys.stdin.readlines()
videos = []
for line in lines:
    try:
        data = json.loads(line.strip())
        videos.append({
            'title': data.get('title','')[:80],
            'views': data.get('view_count',0),
            'likes': data.get('like_count',0),
            'date': data.get('upload_date',''),
            'duration': data.get('duration',0)
        })
    except:
        pass
import io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')
print(f'Total videos: {len(videos)}')
# Categorize by topic keywords
categories = {}
for v in videos:
    t = v['title'].lower()
    if 'codie' in t or 'boring' in t or 'nham chan' in t or 'nhàm chán' in t:
        categories.setdefault('codie_sanchez', []).append(v)
    elif 'warren' in t or 'buffett' in t:
        categories.setdefault('buffett', []).append(v)
    elif 'elon' in t or 'musk' in t:
        categories.setdefault('musk', []).append(v)
    elif 'robert' in t or 'kiyosaki' in t:
        categories.setdefault('kiyosaki', []).append(v)
    elif any(x in t for x in ['dong tien', 'dòng tiền', 'cashflow', 'cash flow']):
        categories.setdefault('cashflow', []).append(v)
    elif any(x in t for x in ['tu duy', 'tư duy', 'mindset']):
        categories.setdefault('mindset', []).append(v)

print(f'\\nContent categories found:')
for cat, vids in sorted(categories.items(), key=lambda x: -len(x[1])):
    avg_views = sum(v['views'] for v in vids) // max(len(vids),1)
    print(f'  {cat}: {len(vids)} videos, avg {avg_views} views')

# Top 10 by views
videos.sort(key=lambda x: -x['views'])
print(f'\\nTop 10 videos by views:')
for v in videos[:10]:
    print(f\"  {v['views']:>8} views | {v['title'][:60]}\")

# Recent 10
videos_by_date = sorted(videos, key=lambda x: -int(x['date'] or '0'))
print(f'\\nRecent 10 videos:')
for v in videos_by_date[:10]:
    print(f\"  {v['date']} | {v['views']:>6} views | {v['title'][:60]}\")
